async function hashBytes(bytes){const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function addFiles(files,sample=false){if(busy)return;let added=0;const errors=[];for(const file of files){
    if(state.photos.length>=MAX_PHOTOS){errors.push(`사진은 최대 ${MAX_PHOTOS}장까지 추가할 수 있어요.`);break;}
    if(!/^image\/(jpeg|png|webp)$/.test(file.type)){errors.push(`${file.name}: JPG, PNG, WEBP 파일만 지원해요.`);continue;}
    if(file.size>15*1024*1024){errors.push(`${file.name}: 15MB보다 커요.`);continue;}
    try{const buffer=await file.arrayBuffer(), fileHash=await hashBytes(buffer);const blobURL=URL.createObjectURL(file);let image;try{image=await loadImage(blobURL);}finally{URL.revokeObjectURL(blobURL);}
      const scale=Math.min(1,3200/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
      // Another upload may have finished while this file was being decoded.
      if(state.photos.length>=MAX_PHOTOS){errors.push(`사진은 최대 ${MAX_PHOTOS}장까지 추가할 수 있어요.`);break;}
      state.photos.push({id:uid(),name:file.name,bytes:file.size,width:canvas.width,height:canvas.height,data:canvas.toDataURL('image/jpeg',.96),fileHash,layout:'auto',status:'pending',sample});added++;
    }catch{errors.push(`${file.name}: 사진을 열 수 없어요.`);}
  }render();persist();if(errors.length)toast(errors.join(' '));else if(added)toast(`사진 ${added}장을 추가했어요. 문제 인식을 시작해주세요.`);
}
const openFiles=()=>{if(!busy)$('#file-input').click();};$('#select-files').onclick=e=>{e.stopPropagation();openFiles();};$('#add-more').onclick=openFiles;$('#dropzone').onclick=openFiles;$('#dropzone').onkeydown=e=>{if(e.target===$('#dropzone')&&['Enter',' '].includes(e.key)){e.preventDefault();openFiles();}};
