$('#analyze').onclick=async()=>{
  if(busy)return;const photos=state.photos.filter(p=>p.status!=='done');if(!photos.length)return;const run=createOcrRun();activeRun=run;busy=true;render();$('#progress-dialog').showModal();setProgress('인식 도구와 한국어 데이터를 준비하고 있어요. 처음에는 조금 걸릴 수 있어요.',1);
  let current=0,success=0;const failures=[];
  try{
    await run.wait(()=>window.Tesseract.createWorker(['kor','eng'],1,{workerPath:new URL('./vendor/worker.min.js',location.href).href,corePath:new URL('./vendor/core/',location.href).href,langPath:new URL('./vendor/lang',location.href).href,workerBlobURL:false,cacheMethod:'none',logger:m=>{if(activeRun===run&&!run.cancelled&&m.status==='recognizing text')setProgress(`${current+1} / ${photos.length} · ${photos[current]?.name} · 글자 인식 ${Math.round(m.progress*100)}%`,Math.min(98,(current+m.progress*.9)/photos.length*100));}}).then(created=>run.attachWorker(created)));
    await run.wait(()=>run.worker.setParameters({tessedit_pageseg_mode:'3',preserve_interword_spaces:'0',user_defined_dpi:'300'}));
    for(current=0;current<photos.length;current++){run.ensureActive();const p=photos[current];try{setProgress(`${current+1} / ${photos.length} · ${p.name} 문제 영역을 나누고 있어요.`,current/photos.length*100);const questions=await run.wait(()=>recognize(p,run,message=>setProgress(`${current+1} / ${photos.length} · ${p.name} · ${message}`,current/photos.length*100)));run.ensureActive();state.questions=state.questions.filter(q=>q.photoId!==p.id);state.questions.push(...questions);p.status='done';success++;persist();}catch(err){if(run.cancelled)break;p.status='error';p.error=err.message||'글자를 읽지 못했어요. 다시 인식해주세요.';failures.push(p.name);}}
  }catch(err){if(!run.cancelled){toast('인식 도구를 준비하지 못했어요. 페이지를 새로고침하고 다시 시도해주세요.');console.error('OCR initialization:',err?.message);}}
  finally{
    await run.dispose();
    if(activeRun===run){activeRun=null;busy=false;$('#progress-dialog').close();render();persist();
      if(run.cancelled){if(success)showTab('review');toast('인식을 중단했어요. 완료된 사진은 유지됩니다.');}
      else if(success){showTab('review');toast(`사진 ${success}장 인식 완료. 문제 영역·제목·중복 후보를 검토해주세요.${failures.length?' 일부 사진은 다시 시도해야 해요.':''}`);}else if(failures.length)toast('사진 인식에 실패했어요. 더 선명한 사진으로 다시 시도해주세요.');
    }
  }
};
function renderReview(){const included=state.questions.filter(q=>!q.excluded),pairs=duplicatePairs(state.questions),groups=groupedQuestions(state.questions);const candidateIds=new Set(pairs.flatMap(p=>[p.a,p.b]));
  $('#review-summary').innerHTML=[['인식한 문제',state.questions.length,'개'],['포함할 문제',included.length,'개'],['중복 후보',pairs.length,'쌍'],['분류한 제목',groups.length,'개']].map(([name,n,unit])=>`<div class="stat"><span>${name}</span><strong>${n}<em>${unit}</em></strong></div>`).join('');$('#duplicate-count').textContent=pairs.length;
  const allTitles=[...new Set(state.questions.map(q=>q.title))];if(!allTitles.includes(titleFilter))titleFilter='';$('#title-filter').innerHTML='<option value="">전체 제목</option>'+allTitles.map(t=>`<option ${t===titleFilter?'selected':''} value="${escapeHTML(t)}">${escapeHTML(t)}</option>`).join('');
  let questions=state.questions.filter(q=>!titleFilter||q.title===titleFilter);if(filter==='duplicates')questions=questions.filter(q=>candidateIds.has(q.id));if(filter==='excluded')questions=questions.filter(q=>q.excluded);else if(filter==='all')questions=questions.filter(q=>!q.excluded);
  $('#question-list').innerHTML=questions.map(q=>{const p=state.photos.find(p=>p.id===q.photoId);const n=state.questions.indexOf(q)+1;return `<article class="question-card ${q.excluded?'excluded':''}" data-question="${q.id}"><div class="question-top"><strong>문제 ${String(n).padStart(2,'0')}</strong><span class="badge ${q.excluded?'excluded':candidateIds.has(q.id)||q.needsBounds||!q.reviewed?'warn':''}">${q.excluded?(q.autoDuplicate?'동일한 원본 · 자동 제외':'제외됨'):candidateIds.has(q.id)?'중복 후보':q.needsBounds?'영역 확인 필요':q.reviewed?'검토 완료':'원본 확인 필요'}</span></div><div class="question-preview"><img src="${q.crop}" alt="문제 ${n} 원본 영역"></div><div class="question-body"><label>분류 제목<input data-edit="title" value="${escapeHTML(q.title)}" aria-label="문제 ${n} 분류 제목"></label><label>인식 텍스트<textarea data-edit="text" aria-label="문제 ${n} 인식 텍스트">${escapeHTML(q.text)}</textarea></label><div class="question-meta">${escapeHTML(p.name)} · 글자 인식 신뢰도 ${q.confidence}%${q.titleInferred?'':' · 제목을 사진에서 확인해주세요'}</div></div><div class="question-actions"><button class="secondary-button" data-action="crop">영역 수정</button><button class="secondary-button" data-action="new">이 사진에 문제 추가</button><button class="secondary-button" data-action="review">${q.reviewed?'검토 되돌리기':'검토 완료'}</button><button class="text-button" data-action="exclude">${q.excluded?'다시 포함':'제외하기'}</button></div></article>`;}).join('');
  $('#review-empty').hidden=state.questions.length>0;
  if(state.questions.length&&!questions.length)$('#question-list').innerHTML='<div class="empty-state"><p>이 조건에 해당하는 문제가 없어요.</p></div>';
  $('#duplicate-panel').innerHTML=pairs.length?comparisonHTML(pairs[0],pairs.length):'';
  $$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));
}
function comparisonHTML(pair,total){const a=state.questions.find(q=>q.id===pair.a),b=state.questions.find(q=>q.id===pair.b);return `<section class="duplicate-comparison"><header><strong>같은 문제인지 확인해주세요 · ${total}쌍 남음</strong><span class="badge warn">${pair.exact?'인식 텍스트가 같아요':`인식 텍스트 ${Math.round(pair.score*100)}% 유사`}</span></header><p class="muted small">문제 번호가 달라도 비교합니다. 보기·수치·그림이 다른 문제는 둘 다 남겨주세요.</p><div class="comparison-pair">${[a,b].map((q,i)=>`<div><p>${i===0?'먼저 추가한 문제':'나중에 추가한 문제'} · ${escapeHTML(q.title)}</p><img src="${q.crop}" alt="${i===0?'먼저':'나중에'} 추가한 중복 후보 원본"><p>${escapeHTML(state.photos.find(p=>p.id===q.photoId).name)}</p></div>`).join('')}</div><div class="comparison-actions"><button class="secondary-button" data-distinct-a="${a.id}" data-distinct-b="${b.id}">서로 다른 문제 · 둘 다 포함</button><button class="primary-button" data-duplicate-remove="${b.id}">같은 문제 · 나중 문제 제외</button></div></section>`;}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderReview();});$('#title-filter').onchange=e=>{titleFilter=e.target.value;renderReview();};
$('#duplicate-panel').onclick=e=>{const remove=e.target.closest('[data-duplicate-remove]');if(remove){const q=state.questions.find(q=>q.id===remove.dataset.duplicateRemove);q.excluded=true;q.autoDuplicate=null;render();persist();}const distinct=e.target.closest('[data-distinct-a]');if(distinct){state.questions.find(q=>q.id===distinct.dataset.distinctB).distinctFrom.push(distinct.dataset.distinctA);render();persist();}};
$('#question-list').onchange=e=>{const card=e.target.closest('[data-question]');if(!card||!e.target.dataset.edit)return;const q=state.questions.find(q=>q.id===card.dataset.question);const prop=e.target.dataset.edit;const value=e.target.value.trim();if(prop==='title'&&!value){e.target.value=q.title;toast('제목을 입력해주세요.');return;}if(prop==='text'&&value!==q.text){q.distinctFrom=[];for(const other of state.questions)other.distinctFrom=other.distinctFrom.filter(id=>id!==q.id);}q[prop]=value;q.reviewed=false;card.querySelector('.badge').textContent='원본 확인 필요';card.querySelector('.badge').className='badge warn';const pairs=duplicatePairs(state.questions);$('#duplicate-count').textContent=pairs.length;$('#duplicate-panel').innerHTML=pairs.length?comparisonHTML(pairs[0],pairs.length):'';persist();};
$('#question-list').onclick=e=>{const button=e.target.closest('[data-action]'),card=e.target.closest('[data-question]');if(!button||!card)return;const q=state.questions.find(q=>q.id===card.dataset.question);const action=button.dataset.action;if(action==='exclude'){q.excluded=!q.excluded;q.autoDuplicate=null;render();persist();}if(action==='review'){q.reviewed=!q.reviewed;if(q.reviewed)q.needsBounds=false;render();persist();}if(action==='crop')openCrop(q,false);if(action==='new')openCrop(q,true);};
async function openCrop(q,isNew){const photo=state.photos.find(p=>p.id===q.photoId);const image=await loadImage(photo.data);cropEdit={q,photo,image,isNew,box:{...q.box}};$('#crop-dialog').showModal();drawCrop();}
function drawCrop(){if(!cropEdit)return;const c=$('#crop-canvas'),{photo,image,box}=cropEdit;c.width=photo.width;c.height=photo.height;const ctx=c.getContext('2d');ctx.drawImage(image,0,0);ctx.fillStyle='#194b3344';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(image,box.x,box.y,box.w,box.h,box.x,box.y,box.w,box.h);ctx.strokeStyle='#36865b';ctx.lineWidth=Math.max(3,photo.width/350);ctx.strokeRect(box.x,box.y,box.w,box.h);for(const key of ['x','y','w','h'])$(`#crop-${key}`).value=box[key];}
function cropPoint(e){const rect=$('#crop-canvas').getBoundingClientRect();return {x:(e.clientX-rect.left)/rect.width*cropEdit.photo.width,y:(e.clientY-rect.top)/rect.height*cropEdit.photo.height};}
$('#crop-canvas').onpointerdown=e=>{dragStart=cropPoint(e);$('#crop-canvas').setPointerCapture(e.pointerId);};$('#crop-canvas').onpointermove=e=>{if(!dragStart)return;const p=cropPoint(e);cropEdit.box=clampBox({x:Math.min(p.x,dragStart.x),y:Math.min(p.y,dragStart.y),w:Math.abs(p.x-dragStart.x),h:Math.abs(p.y-dragStart.y)},cropEdit.photo.width,cropEdit.photo.height);drawCrop();};$('#crop-canvas').onpointerup=()=>{dragStart=null;};$('#crop-canvas').onpointercancel=()=>{dragStart=null;};
for(const key of ['x','y','w','h'])$(`#crop-${key}`).onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value))return;cropEdit.box=clampBox({...cropEdit.box,[key]:value},cropEdit.photo.width,cropEdit.photo.height);drawCrop();};$('#close-crop').onclick=()=>$('#crop-dialog').close();
$('#save-crop').onclick=async()=>{const {q,photo,box,isNew}=cropEdit;const canvas=await cropCanvas(photo,box);const cropHash=await hashBytes(canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data);const updates={box:{...box},crop:canvas.toDataURL('image/jpeg',.91),cropHash,reviewed:false,needsBounds:false,distinctFrom:[],autoDuplicate:null};if(isNew){state.questions.push({...q,...updates,id:uid(),excluded:false,text:'',confidence:0});toast('새 문제 영역을 추가했어요. 인식 텍스트를 입력하거나 원본 모양으로 저장해주세요.');}else{Object.assign(q,updates);toast('영역을 변경했어요. 인식 텍스트는 원본을 보고 맞춰주세요.');}$('#crop-dialog').close();cropEdit=null;render();persist();};
function exportBlocker(){const pairs=duplicatePairs(state.questions),included=state.questions.filter(q=>!q.excluded);if(!included.length)return '저장할 문제가 없어요. 사진을 인식하고 포함할 문제를 선택해주세요.';const pendingPhotos=state.photos.filter(p=>p.status!=='done');if(pendingPhotos.length)return `아직 인식하지 못한 사진 ${pendingPhotos.length}장이 있어요. 사진을 인식하거나 작업에서 삭제해주세요.`;if(pairs.length)return `중복 후보 ${pairs.length}쌍이 남아 있어요. 문제 검토에서 같은 문제인지 확인해주세요.`;const pending=included.filter(q=>!q.reviewed);if(pending.length)return `원본 확인이 필요한 문제 ${pending.length}개가 있어요. 영역·제목을 확인하고 각 문제에서 ‘검토 완료’를 눌러주세요.`;const format=$('input[name="format"]:checked').value,content=$('input[name="content"]:checked').value;if((format==='txt'||content==='text')&&included.some(q=>!q.text.trim()))return '인식 텍스트가 비어 있는 문제가 있어요. 텍스트를 입력하거나 원본 모양 보존으로 저장해주세요.';return '';}
function renderExport(){const groups=groupedQuestions(state.questions);$('#export-groups').innerHTML=groups.length?groups.map((g,i)=>`<div class="export-group"><span class="file-icon">${$('input[name="format"]:checked').value==='pdf'?'P':$('input[name="format"]:checked').value==='txt'?'T':'W'}</span><div><h3>${escapeHTML(g.title)}</h3><small>문제 ${g.questions.length}개 · ${g.questions.filter(q=>q.reviewed).length}개 검토 완료</small></div><button class="text-button" data-export-one="${i}">이 제목만 저장 ↧</button></div>`).join(''):'<div class="empty-state"><p>인식한 문제가 아직 없어요.</p><button class="secondary-button" data-export-upload>사진 추가하기</button></div>';const blocker=exportBlocker();$('#export-alert').hidden=!blocker;$('#export-alert').textContent=blocker;$('#download-all').disabled=!!blocker;}
$$('input[name="format"],input[name="content"]').forEach(i=>i.onchange=renderExport);
async function saveGroups(groups,button){const blocker=exportBlocker();if(blocker){toast(blocker);return;}const options={format:$('input[name="format"]:checked').value,content:$('input[name="content"]:checked').value,includeSource:$('#include-source').checked};button.disabled=true;const label=button.textContent;button.textContent='파일을 만들고 있어요…';try{await downloadGroups(groups,state.photos,options);toast(`${groups.length}개 제목의 파일을 저장했어요.`);}catch(err){console.error('Export:',err);toast('파일 생성에 실패했어요. 작업을 백업한 뒤 다시 시도해주세요.');}finally{button.textContent=label;button.disabled=false;}}
$('#download-all').onclick=e=>saveGroups(groupedQuestions(state.questions),e.currentTarget);$('#export-groups').onclick=e=>{const b=e.target.closest('[data-export-one]');if(b)saveGroups([groupedQuestions(state.questions)[+b.dataset.exportOne]],b);if(e.target.closest('[data-export-upload]'))showTab('upload');};
$('#backup').onclick=()=>{if(!state.photos.length){toast('백업할 작업이 없어요.');return;}download(JSON.stringify({...state,exportedAt:new Date().toISOString()}),`문제모음_작업백업_${new Date().toISOString().slice(0,10)}.json`,'application/json');};
function validateBackup(data){if(data.version!==1||!Array.isArray(data.photos)||!Array.isArray(data.questions)||data.photos.length>MAX_PHOTOS||data.questions.length>MAX_BACKUP_QUESTIONS)throw new Error('잘못된 백업');const ids=new Set();for(const p of data.photos){if(typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||!/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.data)||!Number.isInteger(p.width)||!Number.isInteger(p.height)||p.width<1||p.height<1||p.width>3200||p.height>3200)throw new Error('잘못된 사진');ids.add(p.id);p.status=['done','pending','error'].includes(p.status)?p.status:'pending';p.layout=['auto','one','two'].includes(p.layout)?p.layout:'auto';}const qids=new Set();for(const q of data.questions){if(typeof q.id!=='string'||qids.has(q.id)||!ids.has(q.photoId)||typeof q.title!=='string'||typeof q.text!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(q.crop)||!q.box||!['x','y','w','h'].every(k=>Number.isFinite(q.box[k])))throw new Error('잘못된 문제');qids.add(q.id);const p=data.photos.find(p=>p.id===q.photoId);q.box=clampBox(q.box,p.width,p.height);q.excluded=!!q.excluded;q.reviewed=!!q.reviewed;q.distinctFrom=Array.isArray(q.distinctFrom)?q.distinctFrom.filter(x=>typeof x==='string'):[];}return {version:1,photos:data.photos,questions:data.questions};}
$('#restore-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>MAX_BACKUP_BYTES){toast('백업 파일은 500MB 이하여야 해요.');return;}try{const next=validateBackup(JSON.parse(await file.text()));if(state.photos.length&&!await confirmAction('백업 작업을 열까요?','현재 작업을 백업 파일의 내용으로 바꿉니다. 필요하면 먼저 현재 작업을 백업해주세요.'))return;state=next;persist();showTab(state.questions.length?'review':'upload');toast('백업 작업을 열었어요.');}catch{toast('문제모음에서 저장한 올바른 백업 JSON 파일을 선택해주세요.');}};
$('#reset').onclick=async()=>{if(!state.photos.length)return;if(!await confirmAction('새 작업을 시작할까요?','현재 사진과 문제를 이 브라우저에서 지웁니다. 필요한 파일이나 작업 백업을 먼저 저장해주세요.'))return;state={version:1,photos:[],questions:[]};filter='all';titleFilter='';persist();showTab('upload');toast('새 작업을 시작했어요.');};
$('#sample').onclick=async()=>{if(busy)return;const samples=[{title:'세포의 구조와 기능',name:'예시_세포_01.png',items:[['1. 세포에서 유전 정보를 저장하는 구조는 무엇인가?','① 핵   ② 리보솜   ③ 세포막   ④ 세포벽'],['2. 식물 세포에서만 관찰되는 구조를 고르시오.','① 세포막   ② 미토콘드리아   ③ 엽록체   ④ 핵']]},{title:'세포의 구조와 기능',name:'예시_세포_02.png',items:[['3. 세포에서 유전 정보를 저장하는 구조는 무엇인가?','① 핵   ② 리보솜   ③ 세포막   ④ 세포벽'],['4. 단백질 합성에 관여하는 세포 소기관은?','① 액포   ② 리보솜   ③ 세포벽   ④ 엽록체']]},{title:'물질대사와 에너지',name:'예시_물질대사.png',items:[['1. 세포 호흡에서 주로 생성되는 에너지 운반체는?','① DNA   ② RNA   ③ ATP   ④ 녹말'],['2. 광합성에 필요한 물질을 고르시오.','① 산소   ② 포도당   ③ 이산화 탄소   ④ 단백질']]}];const files=[];for(const s of samples){const c=document.createElement('canvas');c.width=1500;c.height=1100;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#182a20';ctx.font='bold 52px "Malgun Gothic", sans-serif';ctx.fillText(s.title,110,130);ctx.strokeStyle='#b5bdb5';ctx.beginPath();ctx.moveTo(100,175);ctx.lineTo(1400,175);ctx.stroke();ctx.font='30px "Malgun Gothic", sans-serif';s.items.forEach((item,i)=>{const y=290+i*340;ctx.fillText(item[0],110,y);ctx.font='28px "Malgun Gothic", sans-serif';ctx.fillText(item[1],110,y+85);ctx.font='30px "Malgun Gothic", sans-serif';});const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));files.push(new File([blob],s.name,{type:'image/png'}));}await addFiles(files,true);};
